    U.append(("u27", "Describing and comparing", "лу'чше, ху'же · прав, ну'жен · э'тот, тот · кото'рый", [
        ("More and less", "Comparing two things, and naming the most.", [
            ex("Compare with -ее and чем: интере'снее, чем, more interesting than. A few comparatives are irregular and very common: бо'льше more, ме'ньше less, лу'чше better, ху'же worse, ста'рше older, моло'же younger. Са'мый makes the superlative: са'мая интере'сная кни'га.",
               [("интере'сный", "interesting"), ("фильм", "film"), ("Э'та кни'га интере'снее, чем фильм.", "This book is more interesting than the film."), ("э'та", "this (feminine)"),
                ("бо'льше — ме'ньше", "more — less"), ("лу'чше — ху'же", "better — worse"), ("Брат ста'рше, сестра' моло'же.", "My brother is older, my sister younger."),
                ("са'мая интере'сная кни'га", "the most interesting book"), ("ва'жный", "important"), ("тру'дный", "difficult"), ("лёгкий", "easy; light")]),
            lp("лу'чше", ["лу'чше", "ху'же", "бо'льше"]),
            tl("better", "лу'чше"), tl("important", "ва'жный"),
            fl("Матема'тика ", "интере'снее", ", чем фильм.", "Mathematics is more interesting than a film."),
            fl("Брат ", "ста'рше", " меня'.", "My brother is older than me."),
            dc("Э'та кни'га лу'чше, чем фильм."),
            ra("Бо'льше, ме'ньше, лу'чше, ху'же, ста'рше, моло'же. Ва'жный, тру'дный, лёгкий."),
            rm("Э'то са'мая интере'сная кни'га.", ["This is the most interesting book.", "This is a more interesting book.", "This is an interesting film."]),
            cp("интере'сный — интере'снее — са'мый интере'сный", 1),
        ]),
        ("Short forms: прав, ну'жен, до'лжен", "Adjectives have a short form used only as a predicate; here are the ones you will hear most. Adverbs end in -о.", [
            ex("Some adjectives have a short form used only as a predicate: ты прав / ты права', you are right; я согла'сен / согла'сна, I agree; мне ну'жен / нужна' / ну'жно, I need; я до'лжен / должна', I must. Adverbs end in -о and double as it is…: тру'дно, легко', ва'жно, интере'сно.",
               [("Ты прав.", "You are right (to a man)."), ("Ты права'.", "You are right (to a woman)."), ("Я согла'сен.", "I agree (a man speaking)."), ("Я согла'сна.", "I agree (a woman speaking)."),
                ("Мне ну'жен стол.", "I need a table."), ("Мне нужна' кни'га.", "I need a book."), ("Мне ну'жно поду'мать.", "I need to think."), ("Я до'лжен идти'.", "I must go (a man)."),
                ("идти'", "to go (on foot, one way)"), ("Она' должна' рабо'тать.", "She must work."), ("Э'то тру'дно, но интере'сно.", "It's hard, but interesting."), ("легко'", "easy; easily"), ("ва'жно", "important (it is important)")]),
            lp("права'", ["прав", "права'"]),
            tl("I agree (a man speaking)", "я согла'сен"), tl("to go (on foot, one way)", "идти'"),
            fl("Ты ", "прав", ", э'то ва'жно.", "You're right (to a man), this is important."),
            fl("Мне ", "нужна'", " соль.", "I need salt."),
            dc("Я согла'сна. Я должна' идти'."),
            ra("Э'то тру'дно, но интере'сно. А э'то легко' и ва'жно. Я согла'сен, и я до'лжен идти'."),
            rm("Ему' ну'жно бо'льше вре'мени.", ["He needs more time.", "He has a lot of time.", "He needs less time."]),
            cp("ну'жен, нужна', ну'жно", 1),
        ]),
        ("This and that: э'тот, тот", "Э'то alone points; before a noun it agrees. Тот is the one further away.", [
            ex("Э'то alone points: э'то кни'га, this is a book. Before a noun it agrees: э'тот стол, э'та кни'га, э'то окно', э'ти кни'ги. Тот, та, то, те is that one, further away.",
               [("э'тот стол", "this table"), ("э'та кни'га", "this book"), ("э'то окно'", "this window"), ("э'ти кни'ги", "these books"), ("тот дом", "that house"), ("та у'лица", "that street"),
                ("те лю'ди", "those people"), ("Э'тот чай лу'чше, чем тот.", "This tea is better than that one.")]),
            lp("э'ти", ["э'ти", "э'та", "э'то"]),
            tl("this (masculine)", "э'тот"), tl("these", "э'ти"),
            fl("", "Э'та", " кни'га моя', а та — твоя'.", "This book is mine, and that one is yours."),
            fl("Кто ", "те", " лю'ди?", "Who are those people?"),
            dc("Э'тот стол но'вый, а тот ста'рый."),
            ra("Э'тот, э'та, э'то, э'ти. Тот, та, то, те."),
            rm("Э'ти кни'ги интере'снее, чем те.", ["These books are more interesting than those.", "Those books are more interesting than these.", "These books are the most interesting."]),
            cp("э'тот — тот, э'та — та, э'ти — те", 1),
        ]),
        ("Which: кото'рый", "The word that joins a clause to a noun: the gateway to real sentences.", [
            ex("Кото'рый joins a clause to a noun, like which or who. It agrees with the noun in gender and number, and takes the case its own clause needs: челове'к, кото'рый чита'ет; кни'га, кото'рую я чита'ю; го'род, в кото'ром я живу'.",
               [("челове'к, кото'рый чита'ет", "the person who is reading"), ("кни'га, кото'рую я чита'ю", "the book that I am reading"), ("го'род, в кото'ром я живу'", "the city I live in"),
                ("лю'ди, кото'рые зна'ют", "people who know"), ("кото'рая", "which, who (feminine)"), ("Я ви'жу челове'ка, кото'рый ждёт.", "I see a person who is waiting.")]),
            lp("кото'рую", ["кото'рую", "кото'рая", "кото'рые"]),
            tl("which, who (masculine)", "кото'рый"), tl("which, who (plural)", "кото'рые"),
            fl("Э'то кни'га, ", "кото'рую", " я люблю'.", "This is the book that I love."),
            fl("Э'то го'род, ", "в кото'ром", " живёт мой брат.", "This is the city where my brother lives."),
            dc("Челове'к, кото'рый ду'мает."),
            ra("Кни'га, кото'рую я чита'ю, о ко'смосе."),
            rm("Я зна'ю челове'ка, кото'рый живёт на ста'нции.", ["I know a person who lives on the station.", "I know a station where a person lives.", "A person knows that I live on the station."]),
            cp("кото'рый, кото'рая, кото'рое, кото'рые", 1),
        ]),
        ("Reading with кото'рый", "Mira again, in sentences with clauses inside them.", [
            ps("Ми'ра — ро'бот, кото'рый живёт на ста'нции. Ста'нция, на кото'рой она' рабо'тает, лети'т вокру'г Земли'. Ка'ждое у'тро Ми'ра чита'ет кни'ги, кото'рые ей нра'вятся. Са'мая интере'сная кни'га — та, в кото'рой есть зада'чи. Э'ти зада'чи трудне'е, чем те, кото'рые она' реша'ла вчера'.",
               "Mira is a robot who lives on the station. The station she works on flies around the Earth. Every morning Mira reads books that she likes. The most interesting book is the one with problems in it. These problems are harder than the ones she solved yesterday.",
               {"которой": "which (на которой: on which; в которой: in which)", "вокруг": "around", "земли": "the Earth (after вокруг)", "каждое": "every (with a neuter noun)", "нравятся": "please (they); which she likes",
                "станции": "station (на станции: on the station)", "самая": "the most (feminine)", "интересная": "interesting (feminine)", "задачи": "problems, tasks", "труднее": "harder, more difficult", "решала": "was solving, solved (she)"}),
            rm("Э'ти зада'чи трудне'е, чем те.", ["These problems are harder than those.", "Those problems are harder than these.", "These problems are the hardest."]),
            fl("Ми'ра — ро'бот, ", "кото'рый", " живёт на ста'нции.", "Mira is a robot who lives on the station."),
            fl("Са'мая интере'сная кни'га — ", "та", ", в кото'рой есть зада'чи.", "The most interesting book is the one with problems in it."),
            tl("harder, more difficult", "трудне'е"), tl("problems, tasks", "зада'чи"),
            dc("Кни'ги, кото'рые ей нра'вятся."),
            ra("Ста'нция, на кото'рой она' рабо'тает, лети'т вокру'г Земли'."),
        ]),
    ]))

